const money = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const base = {categories:{Gold:['All pieces','Rings','Earrings','Necklaces','Bangles'],Silver:['All pieces','Rings','Bracelets','Necklaces']},rates:{'22K':7000,'18K':5800,'925':90},gst:3,delivery:150,rateUpdated:null,products:[
{id:'g1',name:'The everyday hoops',metal:'Gold',category:'Earrings',purity:'22K',weight:4.2,chargeType:'percent',charge:12,description:'A sculptural twist on a classic silhouette. An illustrative piece for exploring the collection and pricing experience.',photos:['assets/hero.jpg'],tag:'EVERYDAY FAVOURITE'},
{id:'g2',name:'The solitaire ring',metal:'Gold',category:'Rings',purity:'18K',weight:3.5,chargeType:'fixed',charge:2800,description:'A simple, elegant setting for your special moments. Illustrative design; gemstone pricing is not included in this sample.',photos:['assets/ring.jpg'],tag:'A LITTLE CELEBRATION'},
{id:'g3',name:'The golden necklace',metal:'Gold',category:'Necklaces',purity:'22K',weight:8.6,chargeType:'gram',charge:650,description:'A delicate finishing touch, made for layering or wearing on its own. Sample product; actual specifications will be added by the shop.',photos:['assets/necklace.jpg'],tag:'TIMELESS DETAILS'},
{id:'g4',name:'The classic bracelet',metal:'Gold',category:'Bangles',purity:'18K',weight:6.3,chargeType:'percent',charge:10,description:'A polished accent for everyday dressing. This photo and the product specifications are illustrative.',photos:['assets/bangle.jpg'],tag:'SIMPLE & SPECIAL'},
{id:'s1',name:'The silver solitaire',metal:'Silver',category:'Rings',purity:'925',weight:4.8,chargeType:'fixed',charge:650,description:'An illustrative silver-tone ring for trying the silver collection. Final stock and details to be supplied by the shop.',photos:['assets/ring.jpg'],tag:'SILVER EDIT'},
{id:'s2',name:'The silver bracelet',metal:'Silver',category:'Bracelets',purity:'925',weight:12.5,chargeType:'gram',charge:35,description:'A sample bracelet to preview the shopping experience. Photograph is a design reference, not an actual stock image.',photos:['assets/bangle.jpg'],tag:'DESIGN REFERENCE'}],cart:[],orders:[]};
let db;try{db=JSON.parse(localStorage.getItem('lk-preview-v1'))||structuredClone(base)}catch{db=structuredClone(base)}
sessionStorage.removeItem('lk-role');
let role='',metal='Gold',category='All pieces',activeProduct=null,galleryIndex=0,editorPhotos=[],editorId=null,returnFocus=null;
// Catalogue administration stays locked until its production data integration is ready.
const isAdmin=()=>false;
function persist(){try{localStorage.setItem('lk-preview-v1',JSON.stringify(db));return true}catch{toast('Browser storage is full. Please use fewer or smaller photos.');return false}}
function price(p){const value=p.weight*db.rates[p.purity];const shop=p.chargeType==='fixed'?p.charge:p.chargeType==='gram'?p.weight*p.charge:value*p.charge/100;return {value,shop,total:value+shop}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(title,content,subtitle=''){returnFocus=document.activeElement;$('#modalContent').innerHTML=`<div class="modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p class="modal-subtitle">${esc(subtitle)}</p>`:''}</div><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
let pendingAccountAction=null,otpEmail='',authAttempt=0;
const preferredName=()=>auth.state.preferredName;
function closeModal(){pendingAccountAction=null;authAttempt++;$('#modal').close();if(currentRoute?.screen==='detail'){navigate(routePath(metal,category));return}returnFocus?.focus()}
function login(next='account'){
 pendingAccountAction=next;authAttempt++;
 if(!window.LK_AUTH_CONFIG.emailOtpEnabled){modal('Customer accounts are opening soon',`<p>You can browse our collections and keep your favourites in your bag. Email sign-in is being connected.</p><p>For help with a piece, call <a href="tel:+919840763243">+91 98407 63243</a>.</p><button class="primary" data-action="close">Keep browsing</button>`);return}
 modal('Sign in to continue',`<p>We’ll email you a one-time code. No password needed.</p><form id="signInForm"><div class="form-grid"><label class="full">Email address<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="you@example.com"></label></div><p class="auth-error" id="authError" role="alert"></p><button class="primary" type="submit">Send sign-in code <span>↗</span></button></form><p><button class="text-button" data-action="close">Keep browsing</button></p>`);
 const form=$('#signInForm');form.onsubmit=async e=>{e.preventDefault();const email=form.elements.email.value.trim(),attempt=authAttempt;const button=form.querySelector('button');button.disabled=true;$('#authError').textContent='';try{await auth.sendCode(email);if(attempt!==authAttempt)return;otpEmail=email;showCodeForm()}catch(error){if(attempt===authAttempt)$('#authError').textContent=error.message}finally{button.disabled=false}};
}
function showCodeForm(){
 const sentAt=Date.now();
 modal('Check your email',`<p>Enter the sign-in code sent to <strong>${esc(otpEmail)}</strong>.</p><form id="codeForm"><div class="form-grid"><label class="full">One-time code<input name="code" required pattern="[0-9]{6,10}" minlength="6" maxlength="10" inputmode="numeric" autocomplete="one-time-code" placeholder="Enter your code"></label></div><p class="auth-error" id="authError" role="alert"></p><button class="primary" type="submit">Verify and continue <span>↗</span></button></form><p><button class="text-button" id="resendCode">Resend code</button> · <button class="text-button" id="changeEmail">Use another email</button></p>`);
 const form=$('#codeForm');form.onsubmit=async e=>{e.preventDefault();const attempt=authAttempt,button=form.querySelector('button');button.disabled=true;$('#authError').textContent='';try{await auth.verifyCode(otpEmail,form.elements.code.value);if(attempt!==authAttempt)return;if(preferredName())resumeAccountAction();else askPreferredName()}catch(error){if(attempt===authAttempt)$('#authError').textContent=error.message}finally{button.disabled=false}};
 $('#changeEmail').onclick=()=>login(pendingAccountAction||'account');
 $('#resendCode').onclick=async e=>{if(Date.now()-sentAt<60000){$('#authError').textContent='Please wait a minute before requesting another code.';return}const button=e.currentTarget,attempt=authAttempt;button.disabled=true;try{await auth.sendCode(otpEmail);if(attempt===authAttempt){showCodeForm();toast('A new code has been sent.')}}catch(error){if(attempt===authAttempt)$('#authError').textContent=error.message}finally{button.disabled=false}};
}
function resumeAccountAction(){const next=pendingAccountAction;pendingAccountAction=null;if(next==='checkout')checkout();else if(next==='orders')orders();else account()}
function askPreferredName(next){
 if(!role)return login(next||'account');if(next)pendingAccountAction=next;
 modal('What should we call you?',`<p>Tell us your preferred name so we can address you comfortably when discussing your order.</p><form id="preferredNameForm"><div class="form-grid"><label class="full">Preferred name<input id="preferredName" name="preferredName" value="${esc(preferredName())}" required maxlength="80" placeholder="e.g. Laksh" autocomplete="nickname" aria-describedby="nameNote"></label></div><p id="nameNote">Saved to your account. You can change it here anytime.</p><p class="auth-error" id="authError" role="alert"></p><button class="primary" type="submit">Save and continue <span>↗</span></button></form>`);
 const input=$('#preferredName');input.oninput=()=>input.setCustomValidity('');
 $('#preferredNameForm').onsubmit=async e=>{e.preventDefault();const name=input.value.trim().replace(/\s+/g,' ');if(!name){input.setCustomValidity('Please enter the name you’d like us to use.');input.reportValidity();return}const button=e.currentTarget.querySelector('button'),attempt=authAttempt;button.disabled=true;$('#authError').textContent='';try{await auth.saveName(name);if(attempt===authAttempt)resumeAccountAction()}catch(error){if(attempt===authAttempt)$('#authError').textContent=error.message}finally{button.disabled=false}};
}
async function signOut(){try{await auth.signOut();pendingAccountAction=null;authAttempt++;$('#modal').close();render();toast('Signed out. You can keep browsing.')}catch(error){toast(error.message)}}
async function account(){if(!auth.state.ready){try{await auth.refresh()}catch(error){toast(error.message);return}}if(!role)return login();if(!preferredName())return askPreferredName('account');modal('Your account',`<h3>Hello, ${esc(preferredName())}.</h3><p>${esc(auth.state.user.email)}</p><div class="admin-tabs"><button data-action="orders">My orders</button><button data-action="editName">Edit preferred name</button></div><button class="secondary" data-action="signOut">Sign out</button>`)}
const PAGE_SIZE=12;
let currentRoute=null, currentKey='', pageNumber=1;
const viewMemory=new Map();
const routePath=(m,c,id)=>'#/'+[m,c,id].filter(Boolean).map(encodeURIComponent).join('/');
function readRoute(){let parts;try{parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean).map(decodeURIComponent)}catch{parts=[]}const [m,c,id]=parts;if(!db.categories[m])return {screen:'home'};if(!c||!db.categories[m].includes(c)||c==='All pieces')return {screen:'categories',metal:m};const p=db.products.find(p=>p.id===id&&p.metal===m&&p.category===c);return {screen:p?'detail':'catalog',metal:m,category:c,id:p?.id}}
function rememberView(){if(currentKey)viewMemory.set(currentKey,{search:$('#search').value,sort:$('#sort').value,page:pageNumber,scroll:window.scrollY})}
function navigate(path,replace=false){rememberView();if(location.hash===path){applyRoute();return}history[replace?'replaceState':'pushState']({},'',path);applyRoute()}
function applyRoute(){pendingAccountAction=null;authAttempt++;if($('#modal').open)$('#modal').close();currentRoute=readRoute();currentKey=location.hash||'#/';const saved=viewMemory.get(currentKey);$('#search').value=saved?.search||'';$('#sort').value=saved?.sort||'featured';pageNumber=saved?.page||1;render();if(currentRoute.screen==='detail')drawProduct(currentRoute.id);requestAnimationFrame(()=>window.scrollTo({top:saved?.scroll||0,behavior:'instant'}))}
function goBack(){if(currentRoute.screen==='detail')navigate(routePath(metal,category));else if(currentRoute.screen==='catalog')navigate(routePath(metal));else navigate('#/')}
function showProduct(id){const p=db.products.find(p=>p.id===id);if(!p)return;if($('#modal').open)$('#modal').close();if(currentRoute?.id===id){drawProduct(id);return}navigate(routePath(p.metal,p.category,p.id))}
function shopInfo(){modal('Visit L K Jewellers',$('#shopInfoTemplate').innerHTML)}
function render(){
 $('#adminNav').hidden=!isAdmin();document.querySelectorAll('.admin-only').forEach(e=>e.hidden=!isAdmin());
 $('#bagCount').textContent=db.cart.reduce((sum,c)=>sum+c.qty,0);$('#year').textContent=new Date().getFullYear();
 const r=currentRoute||{screen:'home'};const home=r.screen==='home',cats=r.screen==='categories';if(r.metal)metal=r.metal;if(r.category)category=r.category;
 $('#homeScreen').hidden=!home;$('#categoryScreen').hidden=!cats;$('#catalogScreen').hidden=home||cats;$('#journeyNav').hidden=home;$('#searchBtn').hidden=home||cats;
 $('#breadcrumbs').innerHTML=`<button data-home>Home</button>${!home?`<span>/</span>${cats?`<span aria-current="page">${esc(metal)}</span>`:`<button data-metal="${metal}">${metal}</button><span>/</span><span aria-current="page">${esc(category)}</span>`}`:''}`;
 $('#backBtn').textContent=cats?'← Back to Gold / Silver':'← Back to categories';
 if(home){$('#products').innerHTML='';$('#categoryCards').innerHTML='';return}
 if(cats){$('#products').innerHTML='';$('#categoryTitle').textContent=metal+' collections';$('#categoryCards').innerHTML=db.categories[metal].filter(c=>c!=='All pieces').map((c,i)=>{const list=db.products.filter(p=>p.metal===metal&&p.category===c);const cover=categoryCover(metal,c),img=cover.src;return `<div class="category-tile"><button class="category-card ${metal.toLowerCase()}-category" data-category="${esc(c)}"><span class="category-visual">${img?`<img class="${cover.license?'searched-category-image':''}" src="${esc(img)}" alt="" loading="lazy" decoding="async">`:`<span class="category-picture-status">${esc(cover.source)}</span>`}<span class="category-index">${String(i+1).padStart(2,'0')}</span></span><span class="category-caption"><span><strong>${esc(c)}</strong><small>${list.length?list.length+' '+(list.length===1?'piece':'pieces')+' to discover':'Collection coming soon'}</small></span><span aria-hidden="true">→</span></span></button></div>`}).join('')||'<div class="empty"><h3>A new collection awaits.</h3><p>Categories will appear here once the shop adds them.</p></div>';queueMicrotask(()=>ensureCategoryCovers(metal));return}
 $('#categoryCards').innerHTML='';$('#catalogTitle').textContent=category;$('#catalogMetal').textContent=metal.toUpperCase()+' COLLECTION';$('#rateName').textContent=metal==='Gold'?'22K Gold':'925 Silver';$('#rateValue').textContent=money(db.rates[metal==='Gold'?'22K':'925']);
 const query=$('#search').value.toLowerCase().trim();let products=db.products.filter(p=>p.metal===metal&&p.category===category&&(p.name.toLowerCase().includes(query)||p.description.toLowerCase().includes(query)));
 if($('#sort').value==='low')products.sort((a,b)=>price(a).total-price(b).total);if($('#sort').value==='high')products.sort((a,b)=>price(b).total-price(a).total);
 const pages=Math.max(1,Math.ceil(products.length/PAGE_SIZE));pageNumber=Math.max(1,Math.min(pageNumber,pages));const start=(pageNumber-1)*PAGE_SIZE;const visible=products.slice(start,start+PAGE_SIZE);
 $('#resultCount').textContent=products.length?`${start+1}–${Math.min(start+PAGE_SIZE,products.length)} of ${products.length} ${products.length===1?'piece':'pieces'}`:'No pieces found';
 $('#products').innerHTML=visible.length?visible.map(p=>`<article class="product"><button class="product-img" data-product="${esc(p.id)}" aria-label="View ${esc(p.name)}"><span class="product-tag">${esc(p.tag||'NEW TO THE COLLECTION')}</span><img src="${esc(p.photos[0]||'assets/hero.jpg')}" alt="${esc(p.name)} — illustrative photograph" loading="lazy" decoding="async"></button><div class="product-info"><small>${esc(p.purity)} ${esc(p.metal)} · ${p.weight} g</small><button class="product-name" data-product="${esc(p.id)}">${esc(p.name)}</button><div class="product-price"><span>${money(price(p).total)}</span><small>+ GST & delivery</small></div>${isAdmin()?`<div class="product-edit"><button class="text-button" data-edit="${esc(p.id)}">Edit jewel ↗</button><button class="text-button danger" data-delete="${esc(p.id)}">Delete</button></div>`:''}</div></article>`).join(''):`<div class="empty"><h3>${query?'No matching pieces.':'Something lovely is on its way.'}</h3><p>${query?'Try another search or clear the search box.':'This category is ready for the shop to add jewellery.'}</p><button class="secondary" data-action="backCategories">Back to categories</button></div>`;
 $('#pagination').innerHTML=pages>1?`<button class="secondary" data-page="${pageNumber-1}" ${pageNumber===1?'disabled':''}>← Previous</button><span>Page ${pageNumber} of ${pages}</span><button class="secondary" data-page="${pageNumber+1}" ${pageNumber===pages?'disabled':''}>Next →</button>`:'';
}

function policy(){modal('A little clarity, before you shop.',`<div class="eyebrow">OUR SHOPPING POLICY</div><h3>No bargaining.</h3><p>Prices are calculated from the applicable metal rate and the shop charge. GST and delivery are shown separately at checkout.</p><h3>No change-of-mind returns.</h3><p>Please check the design, weight, size and description carefully before ordering.</p><h3>Incorrect or defective item?</h3><p>Keep a clear package-opening video or other appropriate evidence. The shop will review the issue and arrange the applicable resolution. A video is not the only acceptable form of proof. Applicable consumer rights remain unaffected.</p><h3>Delivery & pickup</h3><p>Delivery availability, charges and timing will be confirmed before a real order is accepted. Shop pickup will also be available.</p><div class="notice">Preview only: no real orders or payments are accepted here.</div>`)}
function rates(){modal('Understanding your jewellery price',`<p>Metal value + shop charge = jewellery price. GST and delivery are added at checkout.</p><div class="price-lines"><div><span>22K gold · sample</span><strong>${money(db.rates['22K'])} / g</strong></div><div><span>18K gold · sample</span><strong>${money(db.rates['18K'])} / g</strong></div><div><span>925 silver · sample</span><strong>${money(db.rates['925'])} / g</strong></div></div><div class="notice">These are demonstration rates, not current market prices. A verified, purity-specific rate feed must be connected before sales open. Live rate timestamps will use Indian Standard Time.</div>${db.rateUpdated?`<p>Sample rates edited: ${esc(new Date(db.rateUpdated).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))} IST</p>`:''}${isAdmin()?'<button class="primary" data-action="settings">Edit sample rates</button>':''}`)}
function drawProduct(id){let p=db.products.find(p=>p.id===id);if(!p)return;activeProduct=p;galleryIndex=0;const v=price(p);modal(p.name,`<div class="detail-return"><button data-action="backCatalog" class="back-button">← Back to ${esc(p.category)}</button><button data-action="goHome" class="home-button">Home</button></div><div class="detail"><div><div class="gallery-main"><img id="mainPhoto" src="${esc(p.photos[0])}" alt="${esc(p.name)} — photo 1" data-action="zoom"><div class="gallery-control"><button data-action="prevPhoto" aria-label="Previous photo">←</button><span id="photoCounter">1 / ${p.photos.length}</span><button data-action="nextPhoto" aria-label="Next photo">→</button></div></div><div class="thumbs">${p.photos.map((photo,i)=>`<button data-photo="${i}" class="${i===0?'selected':''}" aria-label="Show photo ${i+1}"><img src="${esc(photo)}" alt="Photo ${i+1}"></button>`).join('')}</div><small>Illustrative product · tap image to enlarge</small></div><div><div class="eyebrow">${esc(p.purity)} ${esc(p.metal)} · ${p.weight} GRAMS</div><h2>${esc(p.name)}</h2><p>${esc(p.description||'Discover this piece in our collection.')}</p><div class="main-price">${money(v.total)}</div><small>Sample price · GST & delivery calculated at checkout</small><div class="price-lines"><div><span>Metal value<small>${p.weight} g × ${money(db.rates[p.purity])}/g</small></span><span>${money(v.value)}</span></div><div><span>Shop charge</span><span>${money(v.shop)}</span></div><div class="total"><span>Jewellery price</span><strong>${money(v.total)}</strong></div></div><button class="primary" data-add-bag="${esc(p.id)}">Add to bag <span>↗</span></button><div class="notice">No bargaining. No change-of-mind returns. Incorrect or defective items can be reviewed with suitable proof.</div></div></div>`);let x=0;$('#mainPhoto').ontouchstart=e=>x=e.changedTouches[0].screenX;$('#mainPhoto').ontouchend=e=>{const dx=e.changedTouches[0].screenX-x;if(Math.abs(dx)>40)gallery(dx<0?galleryIndex+1:galleryIndex-1)}}
function gallery(i){if(!activeProduct)return;galleryIndex=(i+activeProduct.photos.length)%activeProduct.photos.length;$('#mainPhoto').src=activeProduct.photos[galleryIndex];$('#mainPhoto').alt=`${activeProduct.name} — photo ${galleryIndex+1}`;$('#photoCounter').textContent=`${galleryIndex+1} / ${activeProduct.photos.length}`;document.querySelectorAll('[data-photo]').forEach(e=>e.classList.toggle('selected',Number(e.dataset.photo)===galleryIndex))}
function addBag(id){const row=db.cart.find(c=>c.id===id);if(row){if(row.qty>=10)return toast('Maximum 10 per item in this preview.');row.qty++}else db.cart.push({id,qty:1});persist();render();toast('Added to your bag')}
function cartTotal(){return db.cart.reduce((sum,c)=>sum+price(db.products.find(p=>p.id===c.id)).total*c.qty,0)}
function showBag(){db.cart=db.cart.filter(c=>db.products.some(p=>p.id===c.id));const total=cartTotal();modal('Your jewellery bag',db.cart.length?`${db.cart.map(c=>{const p=db.products.find(p=>p.id===c.id);return `<div class="bag-item"><img src="${esc(p.photos[0])}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p>${esc(p.purity)} ${esc(p.metal)} · ${p.weight} g</p><div class="quantity"><button data-qty="${p.id}" data-change="-1" aria-label="Decrease quantity">−</button><span>${c.qty}</span><button data-qty="${p.id}" data-change="1" aria-label="Increase quantity">+</button></div> <button class="text-button" data-remove="${p.id}">Remove</button></div><strong>${money(price(p).total*c.qty)}</strong></div>`}).join('')}<div class="price-lines"><div class="total"><span>Jewellery subtotal</span><strong>${money(total)}</strong></div></div><p>GST and delivery will be shown on the next step. All prices in this preview are illustrative.</p><button class="primary" data-action="checkout">Continue to checkout <span>↗</span></button>`:'<div class="empty"><h3>A little room for something lovely.</h3><p>Your bag is empty. Explore the collections to find your first piece.</p><button class="primary" data-action="close">Explore collections</button></div>')}
async function checkout(){if(!auth.state.ready){try{await auth.refresh()}catch(error){toast(error.message);return}}if(!db.cart.length)return showBag();if(!role)return login('checkout');if(!preferredName())return askPreferredName('checkout');modal('Online ordering opens soon',`<p>Thank you, ${esc(preferredName())}. Your bag is saved on this device.</p><p>We’re preparing verified prices, payments and delivery. No order has been placed and no payment has been taken.</p><a class="primary" href="tel:+919840763243">Call L K Jewellers</a><p><button class="text-button" data-action="close">Keep browsing</button></p>`)}
function updateCheckout(){const delivery=$('#deliveryMethod').value==='delivery';$('#addressLabel').hidden=!delivery;$('#pinLabel').hidden=!delivery;$('#addressLabel textarea').required=delivery;$('#pinLabel input').required=delivery;const sub=cartTotal(),tax=sub*db.gst/100;$('#checkoutTotals').innerHTML=`<div class="price-lines"><div><span>Jewellery subtotal</span><span>${money(sub)}</span></div><div><span>GST (${db.gst}% sample setting)</span><span>${money(tax)}</span></div><div><span>${delivery?'Delivery (sample)':'Shop pickup'}</span><span>${money(delivery?db.delivery:0)}</span></div><div class="total"><span>Total</span><strong>${money(sub+tax+(delivery?db.delivery:0))}</strong></div></div>`}
function orders(){if(!role)return login('orders');modal('Your orders',`<div class="empty"><h3>Online ordering opens soon.</h3><p>Once ordering is available, your confirmed orders will appear here.</p></div>`)}
function dashboard(){if(!isAdmin())return;modal('Your shop, at a glance',`<div class="notice">Admin demonstration only. There is no secure admin login or shared database yet. All changes stay in this browser.</div><div class="admin-tabs"><button data-action="manageCategories">Categories</button><button data-action="addJewel">Add jewellery</button><button data-action="settings">Rates & charges</button><button data-action="orders">Demo orders</button></div><div class="price-lines"><div><span>Jewellery pieces</span><strong>${db.products.length}</strong></div><div><span>Categories</span><strong>${db.categories.Gold.length+db.categories.Silver.length-2}</strong></div><div><span>Local demo orders</span><strong>${db.orders.length}</strong></div></div><h3>One owner. Full control.</h3><p>When real sign-in is connected, one configured admin email will have management access. All other accounts will only be able to browse, order and pay.</p><button class="secondary" data-action="reset">Reset sample catalogue</button>`)}
const coverKey=(m,c)=>JSON.stringify([m,c]);
const coverSearches=new Map();
let searchQueue=Promise.resolve();
const cleanText=value=>new DOMParser().parseFromString(String(value||''),'text/html').body.textContent.trim();
function safeHttps(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}}
function searchTerms(m,c){let name=c.normalize('NFKC').replace(/[_-]/g,' ').trim();const dollar=/\bdollars?\b/i.test(name);let term=name.replace(/\bpendents?\b/ig,'pendant');if(dollar)term+=' pendant Indian jewellery';return {query:`${m.toLowerCase()} ${term}`,fallback:null,words:dollar?['pendant','locket','thali']:name.toLowerCase().split(/\s+/).filter(w=>!['gold','silver','jewellery','jewelry','collection','collections','new'].includes(w)).map(w=>w.replace(/s$/,''))}}
async function queryCoverImages(query,words){const params=new URLSearchParams({action:'query',generator:'search',gsrsearch:query+' filetype:bitmap',gsrnamespace:'6',gsrlimit:'24',prop:'imageinfo',iiprop:'url|size|extmetadata',iiurlwidth:'960',format:'json',origin:'*'});const response=await fetch('https://commons.wikimedia.org/w/api.php?'+params,{signal:AbortSignal.timeout(18000),credentials:'omit'});if(!response.ok)throw Error(response.status===429?'Image search is busy. Please try again shortly.':'Image search is unavailable. Please retry.');const body=await response.json();if(body.error)throw Error('The image search could not complete. Please retry.');const pages=Object.values(body.query?.pages||{});return pages.map(p=>{const info=p.imageinfo?.[0],meta=info?.extmetadata;if(!info||!meta)return null;const title=cleanText(meta.ObjectName?.value||p.title.replace(/^File:/,''));const description=cleanText(meta.ImageDescription?.value);const text=(p.title+' '+description).toLowerCase();if(/\bthali\b/i.test(query)&&!/(thali|thaali)/i.test(text))return null;const license=cleanText(meta.LicenseShortName?.value);const source=safeHttps(info.descriptionurl);const src=safeHttps(info.thumburl||info.url).split('?')[0];if(!src||!source||!/(cc0|cc.by|public domain|pd)/i.test(license)||/(noncommercial|\bnc\b|\bnd\b)/i.test(license))return null;if(Math.min(info.width||0,info.height||0)<450)return null;if(!words.length||!words.some(w=>text.includes(w)))return null;if(/\b(banknote|currency|ribbon|medal of honor|us-moh)\b/i.test(text))return null;let score=words.reduce((s,w)=>s+(p.title.toLowerCase().includes(w)?25:text.includes(w)?5:0),0);if(/museum|\bmet\b|bce|century|findid|archaeolog|ancient/i.test(p.title))score-=12;if(/jewell?ery|modern|studio/i.test(p.title))score+=12;return {id:String(p.pageid),src,title,creator:cleanText(meta.Artist?.value||'Creator not listed'),license,licenseUrl:safeHttps((meta.LicenseUrl?.value||'').replace(/^http:/,'https:')),source,score};}).filter(Boolean).sort((a,b)=>b.score-a.score).slice(0,8)}
function coverRecord(m,c){return db.categorySearchResults?.[coverKey(m,c)]}
function categoryCover(m,c){const custom=db.categoryCovers?.[coverKey(m,c)];if(custom)return {src:custom,source:'Your uploaded picture'};const record=coverRecord(m,c);if(record?.selected)return {...record.selected,sourceLabel:'Found by keyword search'};if(record)return {src:null,source:record.error||'No suitable image found. Refine the search.'};const product=db.products.find(p=>p.metal===m&&p.category===c&&p.photos?.length);if(product)return {src:product.photos[0],source:'Existing jewellery photo'};return {src:null,source:coverSearches.has(coverKey(m,c))?'Searching for a matching picture…':'Finding a matching picture…'}}
function refreshCoverUI(m,c){if(currentRoute?.screen==='categories'&&metal===m)render();const editor=$('#coverSearchEditor');if(editor?.dataset.category===c&&editor.dataset.metal===m)renderSearchResults(m,c)}
async function searchCategoryCover(m,c,{force=false,query=null}={}){const key=coverKey(m,c);if(coverSearches.has(key))return coverSearches.get(key);if(!force&&coverRecord(m,c))return coverRecord(m,c);const terms=searchTerms(m,c);const work=searchQueue.catch(()=>{}).then(async()=>{let results=[],actual=query||terms.query,error=null;try{results=await queryCoverImages(actual,query?searchTerms(m,query).words:terms.words);if(!results.length&&!query&&terms.fallback){actual=terms.fallback;results=await queryCoverImages(actual,query?searchTerms(m,query).words:terms.words)}}catch(e){error=e.name==='TimeoutError'?'Image search timed out. Please retry.':e.message}if(!db.categories[m].includes(c))return null;const old=coverRecord(m,c);const record=error&&old?.selected?{...old,error}:{query:actual,results,selected:results[0]||null,error,updated:new Date().toISOString()};db.categorySearchResults={...(db.categorySearchResults||{}),[key]:record};persist();return record}).finally(()=>{coverSearches.delete(key);refreshCoverUI(m,c)});coverSearches.set(key,work);searchQueue=work;return work}
function ensureCategoryCovers(m){for(const c of db.categories[m].filter(c=>c!=='All pieces')){if(db.categoryCovers?.[coverKey(m,c)]||coverRecord(m,c)||db.products.some(p=>p.metal===m&&p.category===c&&p.photos?.length))continue;searchCategoryCover(m,c)}}
function imageCredits(){const entries=[];for(const m of ['Gold','Silver']){for(const c of db.categories[m].filter(c=>c!=='All pieces')){const cover=categoryCover(m,c);if(cover.license&&cover.source)entries.push(`<section class="image-credit-entry"><h3>${esc(m)} · ${esc(c)}</h3>${coverCredit(cover)}</section>`)}}modal('Image credits',entries.length?entries.join(''):'<p>No externally attributed category pictures are currently selected in this browser.</p>')}
function coverCredit(cover){return cover.source&&cover.license?`<div class="cover-credit"><a href="${esc(cover.source)}" target="_blank" rel="noopener">${esc(cover.title)} · ${esc(cover.creator)}</a> · ${cover.licenseUrl?`<a href="${esc(cover.licenseUrl)}" target="_blank" rel="noopener">${esc(cover.license)}</a>`:esc(cover.license)} · Resized</div>`:''}
function saveCategoryCover(m,c,src){const previous=db.categoryCovers;const next={...(previous||{})};if(src)next[coverKey(m,c)]=src;else delete next[coverKey(m,c)];db.categoryCovers=next;if(!persist()){db.categoryCovers=previous;return false}render();return true}
function renderSearchResults(m,c){const host=$('#liveCoverResults');if(!host)return;const record=coverRecord(m,c),busy=coverSearches.has(coverKey(m,c));host.innerHTML=busy?'<p class="search-status" role="status">Searching the web for matching jewellery pictures…</p>':record?.results?.length?`<p class="search-status">Results for “${esc(record.query)}”. The first match is selected automatically; choose another if you prefer.</p><div class="search-result-grid">${record.results.map((r,i)=>`<div><button class="search-result ${record.selected?.id===r.id?'chosen':''}" data-search-result="${i}" data-cover-name="${esc(c)}"><img src="${esc(r.src)}" alt="${esc(r.title)}" loading="lazy"><span>${esc(r.title)}</span><small>${record.selected?.id===r.id?'Selected':'Use this picture'}</small></button>${coverCredit(r)}</div>`).join('')}</div>`:`<p class="search-status" role="status">${esc(record?.error||'No suitable image found for this search. Try more specific words or upload a picture. No generic photo has been substituted.')}</p>`;const cover=categoryCover(m,c);$('#coverCurrent').innerHTML=cover.src?`<img class="cover-large" src="${esc(cover.src)}" alt="Current category cover">${coverCredit(cover)}`:'<div class="cover-empty">No picture selected</div>'}
function editCategoryCover(c){if(!isAdmin()||!db.categories[metal].includes(c))return;const m=metal;modal(`${c} · find a category picture`,`<div id="coverSearchEditor" data-category="${esc(c)}" data-metal="${m}"><div class="cover-editor"><div id="coverCurrent"></div><div><h3>Search for this category.</h3><p>Search uses your category name and metal. “Dollar” is interpreted as an Indian jewellery pendant, not currency.</p><form id="coverSearchForm"><label class="cover-query-label">Search words<input id="coverQuery" required maxlength="100" value="${esc(coverRecord(m,c)?.query||searchTerms(m,c).query)}"></label><button class="primary small" type="submit">Search pictures</button></form></div></div><div id="liveCoverResults" aria-live="polite"></div><label class="upload-area">Or upload a category picture<input id="categoryCoverFile" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="sample-note">Search results come from Wikimedia Commons; some jewellery styles may not be available. Category pictures are visual references, not shop inventory.</p><div class="form-actions"><button class="secondary" data-action="manageCategories">Back to categories</button></div></div>`);renderSearchResults(m,c);if(!coverRecord(m,c))searchCategoryCover(m,c).then(()=>{});$('#coverSearchForm').onsubmit=e=>{e.preventDefault();searchCategoryCover(m,c,{force:true,query:$('#coverQuery').value.trim()});renderSearchResults(m,c)};$('#categoryCoverFile').onchange=async e=>{const input=e.currentTarget,file=input.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Choose JPEG, PNG or WebP.');if(file.size>15*1024*1024)return toast('Choose an image under 15 MB.');input.disabled=true;try{const src=await compressPhoto(file);if(isAdmin()&&saveCategoryCover(m,c,src)){renderSearchResults(m,c);toast('Category picture updated.')}}catch{toast('This image could not be read.')}finally{input.disabled=false;input.value=''}}}
function manageCategories(){if(!isAdmin())return;modal(`${metal} categories`,`<p>Add a name and the website searches for a matching picture. Each category has its own search; no common fallback image is used.</p><form id="categoryForm" class="form-grid"><label>New category<input name="category" id="categoryName" required maxlength="40" placeholder="e.g. Pendant or Dollars" autocomplete="off"></label><div style="align-self:end"><button class="primary small" type="submit" style="margin:0">Add & find picture</button></div><p class="full sample-note" id="newCoverNote">The search starts after you add the category.</p></form><div class="managed-category-list">${db.categories[metal].filter(c=>c!=='All pieces').map(c=>{const cover=categoryCover(metal,c);return `<div class="managed-category">${cover.src?`<img class="managed-cover" src="${esc(cover.src)}" alt="${esc(c)} cover" loading="lazy">`:'<div class="managed-cover cover-empty">No picture yet</div>'}<div class="managed-category-info"><strong>${esc(c)}</strong><small>${db.products.filter(p=>p.metal===metal&&p.category===c).length} pieces</small><div class="managed-category-actions"><button class="text-button" data-cover-category="${esc(c)}">Search / change picture</button><button class="text-button" data-rename-category="${esc(c)}">Rename</button><button class="text-button danger" data-delete-category="${esc(c)}">Delete</button></div></div></div>`}).join('')}</div>`);$('#categoryName').oninput=e=>{const c=e.target.value.trim();$('#newCoverNote').textContent=c?'Will search: '+searchTerms(metal,c).query:'The search starts after you add the category.'};$('#categoryForm').onsubmit=e=>{e.preventDefault();const value=new FormData(e.currentTarget).get('category').trim();if(!value)return;if(db.categories[metal].some(c=>c.toLowerCase()===value.toLowerCase()))return toast('That category already exists.');db.categories[metal].push(value);if(!persist()){db.categories[metal].pop();return}render();searchCategoryCover(metal,value);editCategoryCover(value)}}

function editJewel(id){if(!isAdmin())return;const p=db.products.find(p=>p.id===id)||{name:'',metal,category:currentRoute?.category||db.categories[metal][1],purity:metal==='Gold'?'22K':'925',weight:'',chargeType:'fixed',charge:0,description:'',photos:[]};editorId=id||null;editorPhotos=[...p.photos];modal(id?'Edit jewellery':'Add a little treasure',`<form id="jewelForm"><div class="form-grid"><label class="full">Jewellery name<input name="name" value="${esc(p.name)}" maxlength="80" required></label><label>Metal<select name="metal" id="editorMetal"><option ${p.metal==='Gold'?'selected':''}>Gold</option><option ${p.metal==='Silver'?'selected':''}>Silver</option></select></label><label>Category<select name="category" id="editorCategory" required></select></label><label>Purity<select name="purity" id="editorPurity"></select></label><label>Weight in grams<input name="weight" type="number" min="0.001" max="10000" step="0.001" value="${p.weight}" required></label><label>Shop charge type<select name="chargeType"><option value="fixed" ${p.chargeType==='fixed'?'selected':''}>Fixed amount (₹)</option><option value="gram" ${p.chargeType==='gram'?'selected':''}>Per gram (₹/g)</option><option value="percent" ${p.chargeType==='percent'?'selected':''}>Percentage of metal value (%)</option></select></label><label>Shop charge value<input name="charge" type="number" min="0" max="10000000" step="0.01" value="${p.charge}" required></label><label class="full">Description (optional)<textarea name="description" maxlength="1500">${esc(p.description)}</textarea></label></div><h3>Every angle tells a story.</h3><p>Upload several photos. The first is the main photo. Use the arrows to reorder and the star to make any photo the main image.</p><label class="upload-area">+ Add jewellery photos<input id="photoUpload" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div id="photoList" class="photo-list"></div><div class="notice">Preview storage: up to 8 photos per jewel, compressed and saved only in this browser.</div><div class="form-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button type="submit" class="primary">${id?'Save changes':'Add jewellery'} <span>↗</span></button></div></form>`);
 const updateOptions=()=>{const m=$('#editorMetal').value;$('#editorCategory').innerHTML=db.categories[m].filter(c=>c!=='All pieces').map(c=>`<option ${c===p.category?'selected':''}>${esc(c)}</option>`).join('');$('#editorPurity').innerHTML=(m==='Gold'?['22K','18K']:['925']).map(v=>`<option ${v===p.purity?'selected':''}>${v}</option>`).join('')};updateOptions();$('#editorMetal').onchange=updateOptions;photoList();$('#photoUpload').onchange=async e=>{const files=[...e.target.files];if(files.length+editorPhotos.length>8)return toast('Please use a maximum of 8 photos.');const submit=$('#jewelForm button[type="submit"]');submit.disabled=true;try{for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Please choose JPEG, PNG or WebP photos.');if(file.size>15*1024*1024)throw Error('Each photo must be under 15 MB.');editorPhotos.push(await compressPhoto(file))}photoList()}catch(err){toast(err.message)}finally{submit.disabled=false;e.target.value=''}};
 $('#jewelForm').onsubmit=e=>{e.preventDefault();if(!isAdmin())return;if(!editorPhotos.length)return toast('Add at least one photo to continue.');const f=new FormData(e.currentTarget);const item={id:editorId||crypto.randomUUID(),name:f.get('name').trim(),metal:f.get('metal'),category:f.get('category'),purity:f.get('purity'),weight:Number(f.get('weight')),chargeType:f.get('chargeType'),charge:Number(f.get('charge')),description:f.get('description').trim(),photos:[...editorPhotos],tag:'NEW TO THE COLLECTION'};if(!item.name||!item.category)return toast('Please add a name and category.');if(item.chargeType==='percent'&&item.charge>100)return toast('Percentage must be between 0 and 100.');const old=[...db.products];if(editorId)db.products=db.products.map(x=>x.id===editorId?item:x);else db.products.push(item);if(!persist()){db.products=old;return}$('#modal').close();navigate(routePath(item.metal,item.category));toast('Jewellery saved in this browser.')};
}
function compressPhoto(file){return new Promise((resolve,reject)=>{const src=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');const scale=Math.min(1,900/Math.max(img.width,img.height));canvas.width=Math.max(1,img.width*scale);canvas.height=Math.max(1,img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(src);resolve(canvas.toDataURL('image/jpeg',.78))};img.onerror=()=>{URL.revokeObjectURL(src);reject(Error('This image could not be read.'))};img.src=src})}
function photoList(){$('#photoList').innerHTML=editorPhotos.map((s,i)=>`<div class="photo-item"><img src="${esc(s)}" alt="Uploaded photo ${i+1}"><small>${i===0?'MAIN PHOTO':'PHOTO '+(i+1)}</small><button type="button" data-photo-left="${i}" aria-label="Move photo left" ${i===0?'disabled':''}>←</button><button type="button" data-photo-main="${i}" aria-label="Set as main photo">☆</button><button type="button" data-photo-remove="${i}" aria-label="Remove photo">×</button></div>`).join('')}
function settings(){if(!isAdmin())return;modal('Rates & checkout settings',`<div class="notice">Sample settings only. No live metal-rate provider or payment gateway is connected. Confirm GST treatment and delivery charges before real orders are enabled.</div><form id="settingsForm"><div class="form-grid"><label>22K gold (₹ per gram)<input name="22K" type="number" min="1" max="1000000" step="0.01" value="${db.rates['22K']}" required></label><label>18K gold (₹ per gram)<input name="18K" type="number" min="1" max="1000000" step="0.01" value="${db.rates['18K']}" required></label><label>925 silver (₹ per gram)<input name="925" type="number" min="1" max="1000000" step="0.01" value="${db.rates['925']}" required></label><label>GST percentage (sample)<input name="gst" type="number" min="0" max="100" step="0.01" value="${db.gst}" required></label><label>Delivery charge (sample ₹)<input name="delivery" type="number" min="0" max="100000" step="1" value="${db.delivery}" required></label></div><p style="margin-top:20px">In this preview, GST is applied to jewellery value plus shop charge. Delivery is shown separately. Shop charges are set individually on each jewel.</p><button class="primary" type="submit">Save sample settings</button></form>`);$('#settingsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);for(const key of ['22K','18K','925'])db.rates[key]=Number(f.get(key));db.gst=Number(f.get('gst'));db.delivery=Number(f.get('delivery'));db.rateUpdated=new Date().toISOString();persist();render();closeModal();toast('Sample rates and checkout settings updated.')}}
const actions={editName:()=>askPreferredName('account'),checkoutName:()=>askPreferredName('checkout'),signOut,imageCredits,shopInfo,goHome:()=>navigate('#/'),backCatalog:()=>navigate(routePath(metal,category)),backCategories:()=>navigate(routePath(metal)),close:closeModal,policy,rates,dashboard,manageCategories,addJewel:()=>editJewel(),settings,orders,checkout,prevPhoto:()=>gallery(galleryIndex-1),nextPhoto:()=>gallery(galleryIndex+1),zoom:()=>{const p=activeProduct;modal(p.name,`<img class="full-image" src="${esc(p.photos[galleryIndex])}" alt="${esc(p.name)}"><button class="secondary" data-product="${p.id}">← Back to jewellery</button>`)},reset:()=>{if(!isAdmin())return;if(confirm('Reset sample products, categories and rates? Demo orders and your bag will also be cleared in this browser.')){db=structuredClone(base);persist();metal='Gold';category='All pieces';$('#modal').close();navigate('#/');toast('Sample catalogue restored.')}}};
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-action],[data-home]');if(!t)return;const d=t.dataset;if(d.coverCategory&&isAdmin()){editCategoryCover(d.coverCategory);return}if(d.searchResult!==undefined&&isAdmin()){const record=coverRecord(metal,d.coverName),picked=record?.results[Number(d.searchResult)];if(picked){record.selected=picked;saveCategoryCover(metal,d.coverName,null);persist();refreshCoverUI(metal,d.coverName);toast('Category picture selected.')}return}if(d.home!==undefined){e.preventDefault();navigate('#/');return}if(d.page){pageNumber=Number(d.page);render();$('#catalogTitle').scrollIntoView({behavior:'instant'});return}if(d.action&&actions[d.action])return actions[d.action]();if(d.metal){navigate(routePath(d.metal));return}if(d.category){navigate(routePath(metal,d.category));return}if(d.product)showProduct(d.product);if(d.photo!==undefined)gallery(Number(d.photo));if(d.addBag)addBag(d.addBag);if(d.edit)editJewel(d.edit);if(d.delete&&isAdmin()){if(confirm('Delete this jewellery piece from the demo catalogue?')){db.products=db.products.filter(p=>p.id!==d.delete);db.cart=db.cart.filter(c=>c.id!==d.delete);persist();render();toast('Jewellery deleted.')}}if(d.qty){const c=db.cart.find(c=>c.id===d.qty);c.qty+=Number(d.change);c.qty=Math.min(10,c.qty);db.cart=db.cart.filter(c=>c.qty>0);persist();render();showBag()}if(d.remove){db.cart=db.cart.filter(c=>c.id!==d.remove);persist();render();showBag()}if(d.deleteCategory&&isAdmin()){if(db.products.some(p=>p.metal===metal&&p.category===d.deleteCategory))return toast('Move or delete the jewellery in this category first.');if(confirm('Delete category '+d.deleteCategory+'?')){db.categories[metal]=db.categories[metal].filter(c=>c!==d.deleteCategory);if(db.categoryCovers)delete db.categoryCovers[coverKey(metal,d.deleteCategory)];if(db.categorySearchResults)delete db.categorySearchResults[coverKey(metal,d.deleteCategory)];if(category===d.deleteCategory)category='All pieces';persist();render();manageCategories()}}if(d.renameCategory&&isAdmin()){const next=prompt('New category name',d.renameCategory)?.trim();if(!next||next===d.renameCategory)return;if(next.length>40||db.categories[metal].some(c=>c.toLowerCase()===next.toLowerCase()))return toast('Use a unique category name under 40 characters.');db.categories[metal]=db.categories[metal].map(c=>c===d.renameCategory?next:c);if(db.categoryCovers?.[coverKey(metal,d.renameCategory)]){db.categoryCovers[coverKey(metal,next)]=db.categoryCovers[coverKey(metal,d.renameCategory)];delete db.categoryCovers[coverKey(metal,d.renameCategory)];}if(db.categorySearchResults)delete db.categorySearchResults[coverKey(metal,d.renameCategory)];db.products.forEach(p=>{if(p.metal===metal&&p.category===d.renameCategory)p.category=next});if(category===d.renameCategory)category=next;persist();render();manageCategories()}if(d.photoLeft!==undefined&&isAdmin()){const i=Number(d.photoLeft);[editorPhotos[i-1],editorPhotos[i]]=[editorPhotos[i],editorPhotos[i-1]];photoList()}if(d.photoMain!==undefined&&isAdmin()){editorPhotos.unshift(editorPhotos.splice(Number(d.photoMain),1)[0]);photoList()}if(d.photoRemove!==undefined&&isAdmin()){editorPhotos.splice(Number(d.photoRemove),1);photoList()}});
